package com.game_manager.gm.report;
import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*; import com.game_manager.gm.document.DocumentService; import com.game_manager.gm.jobs.*; import com.game_manager.gm.notification.NotificationService; import io.micrometer.core.instrument.simple.SimpleMeterRegistry; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test; import tools.jackson.databind.ObjectMapper;
class ReportJobHandlerTest {
 @Test void completesStoresPrivateDocumentAndNotifiesOwner(){ReportRequestRepository repository=mock(ReportRequestRepository.class);ReportGenerator generator=mock(ReportGenerator.class);DocumentService documents=mock(DocumentService.class);NotificationService notifications=mock(NotificationService.class);UUID reportId=UUID.randomUUID(),owner=UUID.randomUUID(),documentId=UUID.randomUUID();ReportRequest request=new ReportRequest();request.setId(reportId);request.setOwnerId(owner);request.setDefinitionKey("orders");request.setFormat(ReportFormat.CSV);request.setPermissionSnapshot("REPORT_READ,ORDER_READ_ALL,RESERVATION_READ_ALL");request.setSnapshotAt(Instant.parse("2026-01-01T00:00:00Z"));request.setStatus(ReportStatus.QUEUED);when(repository.findById(reportId)).thenReturn(Optional.of(request));when(repository.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));when(generator.generate(request,null)).thenReturn(new ReportGenerator.Generated("report".getBytes(),"text/csv","csv",1));when(documents.storeGenerated(eq(owner),anyString(),eq("text/csv"),any())).thenReturn(documentId);ReportJobHandler handler=new ReportJobHandler(repository,generator,documents,new ObjectMapper(),Clock.fixed(Instant.parse("2026-01-02T00:00:00Z"),ZoneOffset.UTC),new SimpleMeterRegistry(),notifications);JobRecord job=new JobRecord(UUID.randomUUID(),ReportService.JOB_TYPE,"{\"reportId\":\""+reportId+"\"}","correlation",1,3,60,UUID.randomUUID(),Instant.now().plusSeconds(60));handler.handle(job,mock(JobContext.class));assertThat(request.getStatus()).isEqualTo(ReportStatus.COMPLETED);assertThat(request.getDocumentId()).isEqualTo(documentId);verify(notifications).reportCompleted(owner,reportId,"orders");}
}
